import sys
from decimal import Decimal, ROUND_HALF_UP


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 3:
            continue
        try:
            a = Decimal(parts[0])
            op = parts[1]
            b = Decimal(parts[2])
        except Exception:
            continue

        if op == "+":
            result = a + b
        elif op == "-":
            result = a - b
        elif op == "*":
            result = a * b
        elif op == "/":
            if b == 0:
                print("ERROR")
                continue
            result = (a / b).quantize(Decimal("1e-10"), rounding=ROUND_HALF_UP)
        else:
            continue

        # Format result
        if result == int(result):
            print(str(int(result)))
        elif result == 0:
            print("0")
        else:
            print(str(result).rstrip('0').rstrip('.')


if __name__ == "__main__":
    main()
